B.aaS=new A.R([B.n,"Account gi\xe0 in partita o in matchmaking su un altro dispositivo.",B.m,"La cuenta ya est\xe1 en una partida o buscando rival en otro dispositivo.",B.k,"\u3053\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u306f\u5225\u306e\u7aef\u672b\u3067\u5bfe\u6226\u4e2d\u3001\u307e\u305f\u306f\u30de\u30c3\u30c1\u30f3\u30b0\u4e2d\u3067\u3059\u3002",B.j,"\uc774 \uacc4\uc815\uc740 \ub2e4\ub978 \uae30\uae30\uc5d0\uc11c \ub300\uc804 \ub610\ub294 \ub9e4\uce6d \uc911\uc785\ub2c8\ub2e4.",B.i,"\u6b64\u8d26\u53f7\u5df2\u5728\u53e6\u4e00\u53f0\u8bbe\u5907\u4e0a\u5bf9\u6218\u6216\u5339\u914d\u4e2d\u3002",B.l,"Dieses Konto spielt oder sucht bereits auf einem anderen Ger\xe4t."],t.R)
B.aaw=new A.R([B.n,"Mazzo salvato nel cloud.",B.m,"Mazo guardado en la nube.",B.k,"\u30c7\u30c3\u30ad\u3092\u30af\u30e9\u30a6\u30c9\u306b\u4fdd\u5b58\u3057\u307e\u3057\u305f\u3002",B.j,"\ub371\uc744 \ud074\ub77c\uc6b0\ub4dc\uc5d0 \uc800\uc7a5\ud588\uc2b5\ub2c8\ub2e4.",B.i,"\u724c\u7ec4\u5df2\u4fdd\u5b58\u5230\u4e91\u7aef\u3002",B.l,"Deck in der Cloud gespeichert."],t.R)
B.aa1=new A.R([B.n,"Mazzo modificato su un altro dispositivo. Le modifiche locali non sono sincronizzate.",B.m,"Mazo modificado en otro dispositivo. Los cambios locales no est\xe1n sincronizados.",B.k,"\u5225\u306e\u7aef\u672b\u3067\u30c7\u30c3\u30ad\u304c\u5909\u66f4\u3055\u308c\u307e\u3057\u305f\u3002\u30ed\u30fc\u30ab\u30eb\u306e\u5909\u66f4\u306f\u672a\u540c\u671f\u3067\u3059\u3002",B.j,"\ub2e4\ub978 \uae30\uae30\uc5d0\uc11c \ub371\uc774 \ubcc0\uacbd\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ub85c\uceec \ubcc0\uacbd \uc0ac\ud56d\uc740 \ub3d9\uae30\ud654\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.",B.i,"\u724c\u7ec4\u5df2\u5728\u53e6\u4e00\u53f0\u8bbe\u5907\u4e0a\u66f4\u6539\u3002\u672c\u5730\u66f4\u6539\u5c1a\u672a\u540c\u6b65\u3002",B.l,"Deck auf einem anderen Ger\xe4t ge\xe4ndert. Lokale \xc4nderungen sind nicht synchronisiert."],t.R)
B.a9i=new A.R([B.n,"Mazzo salvato solo in locale. Sincronizzazione cloud non riuscita.",B.m,"Mazo guardado solo localmente. Fall\xf3 la sincronizaci\xf3n.",B.k,"\u30c7\u30c3\u30ad\u306f\u7aef\u672b\u306b\u4fdd\u5b58\u3055\u308c\u307e\u3057\u305f\u3002\u30af\u30e9\u30a6\u30c9\u540c\u671f\u306b\u5931\u6557\u3057\u307e\u3057\u305f\u3002",B.j,"\ub371\uc774 \uae30\uae30\uc5d0\ub9cc \uc800\uc7a5\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ud074\ub77c\uc6b0\ub4dc \ub3d9\uae30\ud654\uc5d0 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4.",B.i,"\u724c\u7ec4\u4ec5\u4fdd\u5b58\u5728\u672c\u5730\u3002\u4e91\u540c\u6b65\u5931\u8d25\u3002",B.l,"Deck nur lokal gespeichert. Cloud-Synchronisierung fehlgeschlagen."],t.R)
